import itertools

def get_connected_pairs(k, n):
    # All possible (s, b) pairs such that 1 <= s < b <= n
    all_pairs = [(s, b) for s in range(1, n + 1) for b in range(s + 1, n + 1)]

    # We need to find all sets of k pairs {(s_i, b_i)} such that
    # s_1 < s_2 < ... < s_k and b_1 < b_2 < ... < b_k
    valid_sets = []
    for combo in itertools.combinations(all_pairs, k):
        # Sort combo by s_i
        sorted_combo = sorted(combo, key=lambda x: x[0])
        # Check if b_i are also sorted
        if all(sorted_combo[i][1] < sorted_combo[i+1][1] for i in range(k-1)):
            valid_sets.append(sorted_combo)
    return valid_sets

def find_connected_pairs(edges):
    # edges is a list of (s, b)
    connected = set()
    # Each edge is a connection
    for s, b in edges:
        connected.add((s, b))

    # Use Floyd-Warshall or similar to find all reachability
    # But the graph is simple (disjoint paths)
    # We can just find all paths
    nodes = set()
    for s, b in edges:
        nodes.add(s)
        nodes.add(b)

    adj = {node: None for node in nodes}
    for s, b in edges:
        adj[s] = b

    for start_node in nodes:
        curr = start_node
        while adj[curr] is not None:
            curr = adj[curr]
            connected.add((start_node, curr))

    return connected

def solve(n):
    for k in range(1, n):
        valid_sets = get_connected_pairs(k, n)
        # We want to check if for every pair of valid sets A and B, 
        # their connected_pairs sets have a non-empty intersection.
        guaranteed = True
        for A in valid_sets:
            conn_A = find_connected_pairs(A)
            for B in valid_sets:
                conn_B = find_connected_pairs(B)
                if not (conn_A & conn_B):
                    guaranteed = False
                    break
            if not guaranteed:
                break
        if guaranteed:
            return k
    return n

for n in range(2, 7):
    print(f"N={n}, k={solve(n)}")

